/**
 * BRANS-PAKETI (diyetisyen) — the weekly plan the DIETITIAN wrote → the patient's week view + a shopping list grouped by
 * the Türkiye Beslenme Rehberi (TÜBER 2022, SB HSGM, Yayın No 1031) food groups. Nothing is generated by a model and no
 * calorie is computed or shown: the list only regroups the dietitian's own words (cost zero).
 *
 * Plan text, one line per meal:  "Pazartesi | Kahvaltı | haşlanmış yumurta, beyaz peynir, domates, tam buğday ekmeği"
 * "Her gün | Ara öğün | 1 porsiyon meyve" repeats the meal on all seven days. Items are split on commas.
 */
export const TUBER_GRUPLARI = ['Süt ve ürünleri', 'Et, yumurta, kurubaklagiller', 'Taze sebze', 'Taze meyve', 'Ekmek ve tahıllar', 'Yağlar', 'Şekerler', 'Diğer'] as const
export type TuberGrubu = (typeof TUBER_GRUPLARI)[number]

export const GUNLER = ['Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi', 'Pazar'] as const
export type Gun = (typeof GUNLER)[number]

/**
 * Turkish-cuisine keyword map → TÜBER group. First match wins. Olives and nuts are counted with fats, as in the Turkish
 * exchange lists dietitians use; the dietitian sees the grouping on the plan preview and can rename an item.
 */
const SOZLUK: Array<[RegExp, TuberGrubu]> = [
  [/baklava|tatlisi|\btatli\b(?!\s*patates)|seker|\bbal\b|recel|pekmez|cikolata|lokum|helva|dondurma|\bkek\b|biskuvi|kurabiye/, 'Şekerler'],
  [/zeytin|aycicek\w*\s*yag|tereyag|(^|\s)yag(\s|$)|margarin|mayonez|ceviz|findik|badem|fistik|kaju/, 'Yağlar'],
  [/\bsut|yogurt|ayran|kefir|peynir|\blor\b|cokelek|labne|kaymak/, 'Süt ve ürünleri'],
  [/taze\s*fasulye/, 'Taze sebze'],
  [/yumurta|tavuk|hindi|\bet\b|\beti\b|\betli\b|kuzu|dana|biftek|pirzola|kiyma|kofte|balik|somon|\bton\b|hamsi|levrek|cupra|sardalya|mercimek|nohut|fasulye|barbunya|borulce|\bbakla\b|kurubaklagil|humus|edamame|tofu/, 'Et, yumurta, kurubaklagiller'],
  [/ekme[kg]|bore[kg]|bulgur|pirinc|pilav|makarna|eriste|yulaf|tahil|galeta|lavas|simit|kraker|misir\s*(gevregi|unu)|kinoa|karabugday|bazlama|gozleme|patates/, 'Ekmek ve tahıllar'],
  [/elma|armut|\bmuz\b|portakal|mandalina|greyfurt|\bnar\b|cile[kg]|kiraz|visne|uzum|kayisi|seftali|\berik\b|karpuz|kavun|incir|ayva|kivi|meyve|yaban\s*mersini|bogurtlen|hurma/, 'Taze meyve'],
  [/domates|salatalik|biber|marul|roka|maydanoz|dereotu|\bnane\b|ispanak|pirasa|kabak|patlican|brokoli|karnabahar|lahana|havuc|kereviz|bezelye|enginar|semizotu|\bturp\b|sogan|sarimsak|mantar|salata|sebze|bamya|pancar|\btere\b/, 'Taze sebze'],
]

/** Turkish letters → ASCII so the patterns can use \b safely (JS word boundaries are ASCII-only). */
function sade(s: string): string {
  return s.toLocaleLowerCase('tr-TR').replace(/ı/g, 'i').replace(/ğ/g, 'g').replace(/ü/g, 'u').replace(/ş/g, 's').replace(/ö/g, 'o').replace(/ç/g, 'c').replace(/â/g, 'a').replace(/î/g, 'i').replace(/û/g, 'u')
}

export function tuberGrubu(yiyecek: string): TuberGrubu {
  const t = sade(String(yiyecek || ''))
  for (const [d, g] of SOZLUK) if (d.test(t)) return g
  return 'Diğer'
}

export interface PlanOgunu { ad: string; yiyecekler: string[] }
export interface HaftalikPlan { gunler: Array<{ gun: Gun; ogunler: PlanOgunu[] }> }

const gunCoz = (s: string): Gun | 'hepsi' | null => {
  const t = s.trim().toLocaleLowerCase('tr-TR')
  if (/^her\s*g[uü]n$/.test(t)) return 'hepsi'
  return GUNLER.find((g) => g.toLocaleLowerCase('tr-TR') === t) || null
}

/** Parse the dietitian's plan text. Invalid lines are returned so the editor can show them. No kcal accepted. */
export function planCoz(metin: string): { plan: HaftalikPlan; hatali: string[] } {
  const gunler = GUNLER.map((gun) => ({ gun, ogunler: [] as PlanOgunu[] }))
  const hatali: string[] = []
  for (const ham of String(metin || '').split(/\r?\n/).slice(0, 200)) {
    const satir = ham.trim()
    if (!satir) continue
    const p = satir.split('|').map((x) => x.trim())
    const gun = p.length === 3 ? gunCoz(p[0]) : null
    if (!gun || !p[1] || !p[2] || /\d+\s*kcal/i.test(satir)) { hatali.push(satir); continue }
    const yiyecekler = p[2].split(',').map((x) => x.trim()).filter(Boolean).slice(0, 20).map((x) => x.slice(0, 80))
    const hedef = gun === 'hepsi' ? gunler : gunler.filter((g) => g.gun === gun)
    for (const g of hedef) {
      const var_ = g.ogunler.find((o) => o.ad.toLocaleLowerCase('tr-TR') === p[1].toLocaleLowerCase('tr-TR'))
      if (var_) var_.yiyecekler.push(...yiyecekler)
      else g.ogunler.push({ ad: p[1].slice(0, 30), yiyecekler })
    }
  }
  return { plan: { gunler }, hatali }
}

/** Unique items of the week grouped by TÜBER group, with how many meals they appear in. */
export function alisverisListesi(plan: HaftalikPlan): Array<{ grup: TuberGrubu; kalemler: Array<{ ad: string; kez: number }> }> {
  const sayac = new Map<string, { ad: string; kez: number; grup: TuberGrubu }>()
  for (const g of plan.gunler) for (const o of g.ogunler) for (const y of o.yiyecekler) {
    // "1 porsiyon meyve", "2 dilim tam buğday ekmeği" → the food word drives the key
    const ad = y.replace(/^\s*[\d.,/½¼]+\s*(adet|dilim|porsiyon|kase|su\s*barda[gğ][iı]|bardak|yemek\s*ka[sş][iı][gğ][iı]|tatl[iı]\s*ka[sş][iı][gğ][iı]|avu[cç]|g|gr|gram|ml)?\s*/i, '').trim() || y.trim()
    const k = ad.toLocaleLowerCase('tr-TR')
    const e = sayac.get(k)
    if (e) e.kez++
    else sayac.set(k, { ad, kez: 1, grup: tuberGrubu(ad) })
  }
  return TUBER_GRUPLARI.map((grup) => ({ grup, kalemler: [...sayac.values()].filter((x) => x.grup === grup).map(({ ad, kez }) => ({ ad, kez })).sort((a, b) => a.ad.localeCompare(b.ad, 'tr')) })).filter((x) => x.kalemler.length)
}
